import kotlinx.coroutines.launch
import org.json.JSONObject

@Composable fun LibraryInsightsDialog(api:NativeApi,onClose:()->Unit){
 val scope=rememberCoroutineScope();var range by remember{mutableStateOf("30")};var report by remember{mutableStateOf<JSONObject?>(null)};var error by remember{mutableStateOf("")};var busy by remember{mutableStateOf(false)};var confirm by remember{mutableStateOf(false)};var confirmation by remember{mutableStateOf("")};var metric by remember{mutableStateOf("catalogViews")}
 val labels=linkedMapOf("visits" to "Website page loads","catalogViews" to "Catalog views","bookViews" to "Book views","searches" to "Catalog searches","zeroResults" to "Zero-result searches","requests" to "Requests","checkouts" to "Checkouts","returns" to "Returns","catalogAdded" to "Copies added")
 fun load(input:JSONObject?=null){scope.launch{busy=true;try{if(input!=null)api.insights(range,input);report=api.insights(range);error=""}catch(e:Exception){error=e.message?:"Analytics unavailable"}finally{busy=false}}}
 LaunchedEffect(range){load()}
 Dialog(onDismissRequest=onClose){Surface{Column(Modifier.padding(20.dp).verticalScroll(rememberScrollState()),verticalArrangement=Arrangement.spacedBy(10.dp)){Text("Library analytics & insights",style=MaterialTheme.typography.titleLarge);Text("Optional self-hosted aggregate counts. No visitor identities, IP addresses, search terms or private reading data.");Row{listOf("7","30","90","all").forEach{r->TextButton(enabled=!busy,onClick={range=r}){Text(if(r=="all")"All time"else "$r days")}}};if(busy)LinearProgressIndicator();report?.let{r->if(r.optString("error").isNotBlank())Text(r.optString("error"),color=MaterialTheme.colorScheme.error);if(r.optBoolean("collectionPausedForRecovery"))Text("Collection paused during recovery review.");Text(if(r.optBoolean("enabled"))"Enabled"else "Paused / not enabled");TextButton(enabled=!busy,onClick={load(JSONObject().put("enabled",!r.optBoolean("enabled")))}){Text(if(r.optBoolean("enabled"))"Pause analytics"else "Enable analytics")};val counts=r.optJSONObject("counts")?:JSONObject();labels.forEach{(key,label)->Text("$label: ${counts.optLong(key)}")};Text("Current catalog: ${r.optInt("catalogSize")} copies");Text("Activity over time",style=MaterialTheme.typography.titleMedium);var expanded by remember{mutableStateOf(false)};Box{OutlinedButton(onClick={expanded=true}){Text(labels[metric]?:metric)};DropdownMenu(expanded=expanded,onDismissRequest={expanded=false}){labels.forEach{(key,label)->DropdownMenuItem(text={Text(label)},onClick={metric=key;expanded=false})}}};val days=r.optJSONArray("daily")?.objects()?:emptyList();val max=maxOf(1L,days.maxOfOrNull{it.optJSONObject("counts")?.optLong(metric)?:0}?:0);days.forEach{d->val n=d.optJSONObject("counts")?.optLong(metric)?:0;Text("${d.optString("date")}: $n");LinearProgressIndicator(progress={n.toFloat()/max},modifier=Modifier.fillMaxWidth())};Text("Popular books",style=MaterialTheme.typography.titleMedium);(r.optJSONArray("popular")?.objects()?:emptyList()).forEach{p->Text("${p.optString("title")}: ${p.optLong("views")} views")};Text("Counts describe activity, not unique people. Charts retain 730 daily buckets; all-time totals continue. Book views reflect public detail opens. Browser privacy preferences are respected.");TextButton(enabled=!busy,onClick={confirm=true;confirmation=""}){Text("Clear analytics",color=MaterialTheme.colorScheme.error)}};if(error.isNotBlank())Text(error,color=MaterialTheme.colorScheme.error);TextButton(onClick=onClose){Text("Close")}}}}
 if(confirm)AlertDialog(onDismissRequest={confirm=false},title={Text("Clear aggregate analytics?")},text={Column{Text("Books, loans and private reading stay. Type CLEAR ANALYTICS.");OutlinedTextField(confirmation,{confirmation=it})}},confirmButton={TextButton(enabled=!busy&&confirmation=="CLEAR ANALYTICS",onClick={confirm=false;load(JSONObject().put("enabled",report?.optBoolean("enabled")?:false).put("clear",true).put("confirmation",confirmation))}){Text("Clear")}},dismissButton={TextButton(onClick={confirm=false}){Text("Cancel")}})
}
